use std::hint::black_box;
#[repr(align(64))]struct Data([usize;2048]);
#[inline(never)]#[unsafe(no_mangle)]pub unsafe fn raw_copy(dst:*mut usize,src:*const usize,n:usize){for i in 0..n{unsafe{dst.add(i).write(src.add(i).read())}}}
fn main(){let a:Vec<_>=std::env::args().collect();let n:usize=a[1].parse().unwrap();let so:usize=a[2].parse().unwrap();let doff:usize=a[3].parse().unwrap();let reps:usize=a[4].parse().unwrap();assert!(so%8==0&&doff%8==0&&n+so/8<=2048&&n+doff/8<=2048);let mut s=Data([0;2048]);let mut d=Data([usize::MAX;2048]);for(i,x)in s.0.iter_mut().enumerate(){*x=i.wrapping_mul(157)^n;}let src=unsafe{s.0.as_ptr().add(so/8)};let dst=unsafe{d.0.as_mut_ptr().add(doff/8)};let t=std::time::Instant::now();for _ in 0..reps{unsafe{raw_copy(black_box(dst),black_box(src),black_box(n))};black_box(dst);}let ns=t.elapsed().as_nanos();assert_eq!(&d.0[doff/8..doff/8+n],&s.0[so/8..so/8+n]);assert!(d.0[..doff/8].iter().all(|&x|x==usize::MAX));assert!(d.0[doff/8+n..].iter().all(|&x|x==usize::MAX));println!("{{\"n\":{n},\"reps\":{reps},\"elapsed_ns\":{ns},\"src_mod64\":{},\"dst_mod64\":{}}}",src as usize%64,dst as usize%64);}
